"""Image-grounded review of v4 train lines 648--882; no model inference.

Every entry is a manual review of both supplied screenshots and action/context.
This records semantic judgments, not a reconstruction of the corruption process.
"""
REVIEWS = {}

def review(line, before, after, evidence, *, pre=None, post=None, status="negative", issues=()):
    assert line not in REVIEWS
    REVIEWS[line] = dict(before=before, after=after, evidence=evidence,
                         precondition=pre, postcondition=post,
                         status=status, issues=list(issues))

def launch(line, app, before, after=None, *, status="negative", issues=()):
    after = after or before
    review(line, before, after,
           f"The after screenshot still shows {after[0].lower() + after[1:].rstrip('.')}. "
           f"Neither {app} nor a newly opened folder exposing its icon is shown.",
           pre=f"{before.rstrip('.')}. Opening {app} requires its launcher icon or a folder containing it to be reached by this action.",
           post=f"{app} opens, or a folder containing its icon opens so that the app can be selected next.",
           status=status, issues=issues)

