def wrong_open(line, intended, actual, before, after, purpose):
    review(line, before, after,
           f"The recorded app argument names {actual}, and the screenshot shows {actual} opened. That app launch does not advance {purpose}; {intended} has not opened.",
           pre=f"{before.rstrip('.')}. The intended next task step requires {intended}; the supplied app argument instead names {actual}.",
           post=f"{intended} is available for {purpose}; completing the subsequent in-app operations is not required in this step.",
           issues=("argument_description_conflict",))

